/**
 * Story player AMD module — handles the chapter reading modal for students.
 *
 * @module     block_playerhud/story_player
 * @copyright  2026 Jean Lúcio
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(['core/ajax', 'core/notification', 'jquery', 'block_playerhud/ws_error'], (Ajax, Notification, $, WsError) => {

    let instanceid = 0;
    let courseid = 0;
    let strings = {};

    let modal = null;
    let contentEl = null;
    let choicesEl = null;
    let titleEl = null;

    /**
     * Show the loading spinner inside the modal body.
     */
    function showLoader() {
        if (contentEl) {
            contentEl.innerHTML =
                '<div class="text-center text-muted py-5">' +
                '<i class="fa fa-circle-o-notch fa-spin fa-3x" aria-hidden="true"></i>' +
                `<p class="mt-2">${strings.loading}</p>` +
                '</div>';
        }
        if (choicesEl) {
            choicesEl.innerHTML = '';
        }
    }

    /**
     * Update the modal title text.
     *
     * @param {string} title New title text.
     */
    function updateTitle(title) {
        if (titleEl && title) {
            const icon = document.createElement('i');
            icon.className = 'fa fa-book me-2';
            icon.setAttribute('aria-hidden', 'true');
            titleEl.replaceChildren(icon, document.createTextNode(title));
        }
    }

    /**
     * Render a node (scene) into the modal.
     *
     * @param {Object} data Web service response data.
     * @param {number} chapterid Current chapter ID.
     */
    function renderNode(data, chapterid) {
        // Render terminal node content before showing the completion UI.
        if (data.node && contentEl) {
            contentEl.innerHTML = data.node.content;
        }

        // Process events here so they are shown regardless of whether the chapter finishes.
        if (data.events && data.events.length > 0) {
            data.events.forEach((evt) => {
                Notification.addNotification({
                    message: evt.msg,
                    type: 'info',
                });
            });
        }

        if (data.finished) {
            // No node means nothing was rendered above — show the icon in the content area.
            if (!data.node && contentEl) {
                contentEl.innerHTML =
                    '<div class="text-center py-5">' +
                    '<i class="fa fa-check-circle fa-3x text-success" aria-hidden="true"></i>' +
                    `<h4 class="mt-3">${strings.completed}</h4>` +
                    '</div>';
            }
            if (choicesEl) {
                const completionbadge = data.node
                    ? ('<div class="w-100 text-center mb-2">' +
                       '<i class="fa fa-check-circle text-success me-1" aria-hidden="true"></i>' +
                       `<span class="fw-bold text-success">${strings.completed}</span>` +
                       '</div>')
                    : '';
                let footer = completionbadge;
                footer += '<button type="button" class="btn btn-secondary me-2"' +
                          ` data-bs-dismiss="modal" data-dismiss="modal">${strings.close}</button>`;
                footer += '<button type="button" class="btn btn-outline-info"' +
                          ' data-action="read-recap"' +
                          ` data-chapterid="${chapterid}">` +
                          `<i class="fa fa-history" aria-hidden="true"></i> ${strings.readAgain}</button>`;
                choicesEl.innerHTML = footer;
            }
            updateChapterCardUI(chapterid);
            return;
        }

        if (!data.node) {
            return;
        }

        if (!choicesEl) {
            return;
        }
        choicesEl.innerHTML = '';

        if (data.node.choices && data.node.choices.length > 0) {
            data.node.choices.forEach((ch) => {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = `btn ${ch.btnclass} m-1 px-4 py-2 text-start`;
                if (ch.disabled) {
                    btn.disabled = true;
                }

                const textSpan = document.createElement('span');
                textSpan.textContent = ch.text;
                btn.appendChild(textSpan);

                // Requirement: class. Rendered as a badge so it keeps contrast on any button colour.
                if (ch.req_class_name) {
                    const classLine = document.createElement('small');
                    classLine.className = 'd-block mt-1';
                    const classBadge = document.createElement('span');
                    classBadge.className = ch.req_class_met ? 'badge bg-success' : 'badge bg-danger';
                    if (!ch.req_class_met) {
                        const lockIcon = document.createElement('i');
                        lockIcon.className = 'fa fa-lock me-1';
                        lockIcon.setAttribute('aria-hidden', 'true');
                        classBadge.appendChild(lockIcon);
                    }
                    classBadge.appendChild(document.createTextNode(ch.str_req_class));
                    classLine.appendChild(classBadge);
                    btn.appendChild(classLine);
                }

                // Requirement: karma.
                if (ch.req_karma_min !== 0) {
                    const karmaLine = document.createElement('small');
                    karmaLine.className = 'd-block mt-1';
                    const karmaBadge = document.createElement('span');
                    karmaBadge.className = ch.req_karma_met ? 'badge bg-success' : 'badge bg-danger';
                    karmaBadge.textContent = ch.req_karma_met ? ch.str_req_karma : ch.str_low_karma;
                    karmaLine.appendChild(karmaBadge);
                    btn.appendChild(karmaLine);
                }

                // Cost: item.
                if (ch.cost_item_name) {
                    const costLine = document.createElement('small');
                    costLine.className = 'd-block mt-1';
                    const costBadge = document.createElement('span');
                    costBadge.className = ch.cost_item_met ? 'badge bg-warning' : 'badge bg-danger';
                    costBadge.textContent = ch.cost_item_met ? ch.str_cost_item : ch.str_missing_item;
                    costLine.appendChild(costBadge);
                    btn.appendChild(costLine);
                }

                btn.addEventListener('click', () => {
                    makeChoice(ch.id, chapterid);
                });
                choicesEl.appendChild(btn);
            });
        } else {
            const closeBtn = document.createElement('button');
            closeBtn.type = 'button';
            closeBtn.className = 'btn btn-secondary';
            closeBtn.setAttribute('data-bs-dismiss', 'modal');
            closeBtn.setAttribute('data-dismiss', 'modal');
            closeBtn.textContent = strings.close;
            choicesEl.appendChild(closeBtn);
        }
    }

    /**
     * Update the chapter card in the list to reflect completion.
     *
     * @param {number} chapterid Chapter ID.
     */
    function updateChapterCardUI(chapterid) {
        const card = document.querySelector(`[data-action="open-chapter"][data-chapterid="${chapterid}"]`);
        if (!card) {
            return;
        }
        // Capture the title before stripping data-* attrs used for modal targeting.
        const chapterTitle = card.getAttribute('data-title') || '';

        card.classList.remove('list-group-item-action', 'ph-chapter-item--available');
        card.classList.add('ph-chapter-item--completed');
        card.removeAttribute('data-action');
        card.removeAttribute('data-bs-toggle');
        card.removeAttribute('data-bs-target');
        card.removeAttribute('data-toggle');
        card.removeAttribute('data-target');
        card.removeAttribute('role');
        card.removeAttribute('tabindex');

        const icon = card.querySelector('i.fa');
        if (icon) {
            icon.className = 'fa fa-check-circle text-success ph-chapter-status-icon';
        }
        if (!card.querySelector('[data-action="read-recap"]')) {
            const footerEl = card.querySelector('.mt-auto.w-100.text-center');
            const recapDiv = document.createElement('div');
            recapDiv.className = 'ph-chapter-recap-wrap';

            const recapBtn = document.createElement('button');
            recapBtn.className = 'btn btn-sm btn-outline-info w-100';
            recapBtn.setAttribute('data-action', 'read-recap');
            recapBtn.setAttribute('data-chapterid', chapterid);
            recapBtn.setAttribute('data-title', chapterTitle);
            recapBtn.setAttribute('data-bs-toggle', 'modal');
            recapBtn.setAttribute('data-bs-target', '#ph-story-modal');
            recapBtn.setAttribute('data-toggle', 'modal');
            recapBtn.setAttribute('data-target', '#ph-story-modal');

            const recapIcon = document.createElement('i');
            recapIcon.className = 'fa fa-history';
            recapIcon.setAttribute('aria-hidden', 'true');
            recapBtn.appendChild(recapIcon);
            recapBtn.appendChild(document.createTextNode(` ${strings.readAgain}`));

            recapDiv.appendChild(recapBtn);

            if (footerEl) {
                footerEl.appendChild(recapDiv);
            } else {
                card.appendChild(recapDiv);
            }
        }
    }

    /**
     * Shows a failed story request inside the modal, in place of the scene.
     *
     * A refusal the server raised on purpose (a locked chapter, a choice no longer available, a
     * missing item) ends there: a dialog on top of the open modal would fight its focus trap.
     * Anything else is a real failure and also opens the exception dialog.
     *
     * @param {Object} ex The failure core/ajax rejected with.
     */
    const showFailure = (ex) => {
        if (contentEl) {
            const errDiv = document.createElement('div');
            errDiv.className = 'alert alert-danger';
            errDiv.setAttribute('role', 'alert');
            errDiv.textContent = ex.message || strings.error;
            contentEl.replaceChildren(errDiv);
        }
        if (!WsError.isExpected(ex)) {
            Notification.exception(ex);
        }
    };

    /**
     * Load the current or starting scene for a chapter.
     *
     * @param {number} chapterid Chapter ID.
     */
    function loadScene(chapterid) {
        showLoader();
        Ajax.call([{
            methodname: 'block_playerhud_load_scene',
            args: {
                instanceid: instanceid,
                courseid: courseid,
                chapterid: chapterid,
                preview: false,
            },
            done: function(data) {
                renderNode(data, chapterid);
            },
            fail: showFailure,
        }]);
    }

    /**
     * Process a player choice and advance the story.
     *
     * @param {number} choiceid Choice ID.
     * @param {number} chapterid Current chapter ID.
     */
    function makeChoice(choiceid, chapterid) {
        showLoader();
        Ajax.call([{
            methodname: 'block_playerhud_make_choice',
            args: {
                instanceid: instanceid,
                courseid: courseid,
                choiceid: choiceid,
                preview: false,
            },
            done: function(data) {
                renderNode(data, chapterid);
            },
            fail: showFailure,
        }]);
    }

    /**
     * Load the full story recap for a completed chapter.
     *
     * @param {number} chapterid Chapter ID.
     */
    function loadRecap(chapterid) {
        showLoader();
        Ajax.call([{
            methodname: 'block_playerhud_load_recap',
            args: {
                instanceid: instanceid,
                courseid: courseid,
                chapterid: chapterid,
            },
            done: function(data) {
                if (contentEl) {
                    contentEl.innerHTML = data.html;
                }
                if (choicesEl) {
                    const closeBtn = document.createElement('button');
                    closeBtn.type = 'button';
                    closeBtn.className = 'btn btn-secondary';
                    closeBtn.setAttribute('data-bs-dismiss', 'modal');
                    closeBtn.setAttribute('data-dismiss', 'modal');
                    closeBtn.textContent = strings.close;
                    choicesEl.innerHTML = '';
                    choicesEl.appendChild(closeBtn);
                }
            },
            fail: showFailure,
        }]);
    }

    return {
        /**
         * Initialise the story player.
         *
         * @param {number} iid Block instance ID.
         * @param {number} cid Course ID.
         * @param {Object} strs Localised string map.
         */
        init: function(iid, cid, strs) {
            instanceid = iid;
            courseid = cid;
            strings = strs;

            modal = document.getElementById('ph-story-modal');
            contentEl = document.getElementById('ph-story-content');
            choicesEl = document.getElementById('ph-story-choices');
            titleEl = document.getElementById('ph-story-title');

            // Move modal to <body> to avoid z-index conflicts with the block drawer.
            if (modal) {
                document.body.appendChild(modal);
            }

            // Use jQuery's .on() so this works in both:
            // - Moodle 4.5 (Bootstrap 4): show.bs.modal fires as a jQuery event.
            // - Moodle 5.1 (Bootstrap 5): Bootstrap 5 also triggers a jQuery event
            //   when window.jQuery is present (via its EventHandler layer).
            if (modal) {
                $(modal).on('show.bs.modal', (e) => {
                    const trigger = e.relatedTarget;
                    if (!trigger) {
                        return;
                    }
                    const chid = parseInt(trigger.getAttribute('data-chapterid'), 10);
                    const title = trigger.getAttribute('data-title') || '';
                    updateTitle(title);
                    showLoader();
                    if (trigger.getAttribute('data-action') === 'read-recap') {
                        loadRecap(chid);
                    } else {
                        loadScene(chid);
                    }
                });
            }

            // The "Read again" button rendered inside the modal footer (by renderNode
            // when a chapter finishes) has no data-toggle — handle it with delegation.
            document.addEventListener('click', (e) => {
                const btn = e.target.closest('[data-action="read-recap"]');
                if (!btn || !modal || !modal.contains(btn)) {
                    return;
                }
                const chid = parseInt(btn.getAttribute('data-chapterid'), 10);
                showLoader();
                loadRecap(chid);
            });
        },
    };
});
